  - Obtain an **API key**.
  - Set up a **quota** (free tier is limited, so be mindful of usage).

---

### **2. Google Sheets + Google Apps Script**
Use **Google Apps Script** to automate the process. Here's how:

#### **Step 1: Prepare Your Google Sheet**
- Column A: **Company Name**
- Columns B, C, D: **Domain**, **Head of Marketing**, **LinkedIn Profile**

#### **Step 2: Write the Script**
```javascript
function getCompanyData() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getActiveSheet();
  const data = sheet.getDataRange().getValues();
  const headers = data[0];
  const rows = data.slice(1);

  const results = [];

  for (let i = 0; i < rows.length; i++) {
    const companyName = rows[i][0];
    const [domain, headOfMarketing, linkedInProfile] = getCompanyInfo(companyName);
    results.push([companyName, domain, headOfMarketing, linkedInProfile]);
  }

  sheet.getRange(2, 1, results.length, 4).setValues(results);
}

function getCompanyInfo(companyName) {
  const domain = getDomain(companyName);
  const headOfMarketing = getHeadOfMarketing(companyName);
  const linkedInProfile = getLinkedInProfile(companyName, headOfMarketing);

  return [domain, headOfMarketing, linkedInProfile];
}

function getDomain(companyName) {
  const query = `site:*.com ${companyName}`;
  const results = searchGoogle(query);
  if (results.length > 0) {
    const url = results[0].link;
    const domain = url.split('/')[2]; // Extract domain from URL
    return domain;
  }
  return "N/A";
}

function getHeadOfMarketing(companyName) {
  const query = `Head of Marketing ${companyName}`;
  const results = searchGoogle(query);
  if (results.length > 0) {
    const title = results[0].title;
    const name = title.split(' ')[0]; // Extract name from title
    return name;
  }
  return "N/A";
}

function getLinkedInProfile(companyName, headOfMarketing) {
  const query = `${headOfMarketing} ${companyName} linkedin`;
  const results = searchGoogle(query);
  if (results.length > 0) {
    const url = results[0].link;
    if (url.includes("linkedin")) {
      return url;
    }
  }
  return "N/A";
}

function searchGoogle(query) {
  // Replace with your CSE ID and API key
  const searchEngineId = "YOUR_CSE_ID";
  const apiKey = "YOUR_API_KEY";
  const url = `https://www.googleapis.com/customsearch/v1?q=${encodeURIComponent(query)}&cx=${searchEngineId}&key=${apiKey}`;
  const response = UrlFetchApp.fetch(url);
  const json = JSON.parse(response.getContentText());
  return json.items || [];
}
```

